inline void require(bool ok,const std::string&s){if(!ok)throw std::runtime_error("source-enriched checkpoint: "+s);}
inline bool same(double a,double b){return std::memcmp(&a,&b,sizeof(double))==0;}
inline std::string quote_text(const std::string&s){std::ostringstream o;o<<std::quoted(s);return o.str();}
struct Stream {std::ifstream in;std::uint64_t hash=14695981039346656037ull;explicit Stream(const std::filesystem::path&p):in(p){require(bool(in),"unreadable file");}std::string line(){std::string x;require(bool(std::getline(in,x)),"truncated file");if(!x.empty()&&x.back()=='\r')x.pop_back();return x;}void add(const std::string&s){for(unsigned char c:s){hash^=c;hash*=1099511628211ull;}}std::size_t count(){const auto s=line();std::size_t p=0;const auto n=std::stoull(s,&p);require(p==s.size()&&n<=20000000,"invalid count");return std::size_t(n);}std::vector<std::string>strings(const std::string&s){std::istringstream i(s);std::vector<std::string>v;while(i>>std::ws&&!i.eof()){require(i.peek()=='\"',"nonquoted field");std::string q;require(bool(i>>std::quoted(q)),"bad quoted field");v.push_back(q);}return v;}
 void parameter(const std::string&expected,std::size_t n,const double*values,eventio::Json*extras=nullptr){auto text=line();std::istringstream i(text);std::string name;int flag=-1;i>>std::quoted(name)>>flag;const bool parsed=bool(i);i>>std::ws;require(parsed&&i.eof()&&name==expected&&flag==0,"parameter registry/order/flag differs: "+expected);std::istringstream v(line());std::size_t size=0;v>>size;require(size==n&&n>0,"parameter shape differs: "+expected);std::ostringstream canonical;canonical<<std::quoted(name)<<" 0 "<<n;eventio::Json saved=eventio::Json::array();for(std::size_t j=0;j<n;++j){double x=0;v>>x;require(bool(v)&&std::isfinite(x),"nonfinite/incomplete parameter: "+name);if(values)require(same(x,values[j]),"parameter value differs: "+name);canonical<<' '<<std::hexfloat<<x;saved.push_back(x);}v>>std::ws;require(v.eof(),"extra parameter values");add(canonical.str()+"\n");if(extras)(*extras)[name]=saved;}
 std::map<std::string,std::string>map(){const auto n=count();add(std::to_string(n)+"\n");std::map<std::string,std::string>out;std::string previous;for(std::size_t j=0;j<n;++j){auto v=strings(line());require(v.size()==2&&(j==0||previous<v[0])&&out.emplace(v[0],v[1]).second,"map registry duplicate/order");previous=v[0];add(quote_text(v[0])+" "+quote_text(v[1])+"\n");}return out;}
};
