 {std::istringstream in(s.line());std::vector<std::string>v;std::string x;while(in>>x)v.push_back(x);require(v.size()==7,"outer state field count");auto integer=[&](std::size_t i){std::size_t used=0;const auto value=std::stoull(v[i],&used);require(used==v[i].size(),"invalid outer integer");return value;};auto real=[&](std::size_t i){std::size_t used=0;const auto value=std::stod(v[i],&used);require(used==v[i].size(),"invalid outer real");return value;};require(integer(0)==2&&real(4)==0&&std::isfinite(real(6))&&real(6)>=0,"AL phase/rho/elapsed header");integer(1);integer(2);integer(3);const auto progress=real(5);require(std::isfinite(progress)||progress==std::numeric_limits<double>::infinity(),"invalid previous progress");}
 require(s.line()=="0"&&s.line()=="0"&&s.count()==1,"old AL duals or absent current state");const auto token=s.strings(s.line());require(token==std::vector<std::string>{meta.at("candidate_state_token")},"candidate token metadata");const auto identity=s.strings(s.line());require(identity.size()==6&&identity[0]==math.identity&&identity[5]=="engineering_recovery_native_pixel_v1","source mathematics/objective identity");
 require(identity[2]==joint_source_math_hash("no_common_budget_in_engineering_recovery")&&identity[3]==joint_source_math_hash(packet.source_hash+"engineering_not_likelihood|"+meta.at("configuration_sha256").get<std::string>()),"engineering budget/statistics identity");
 std::string encoded;for(const auto&x:identity){if(!encoded.empty())encoded+=' ';encoded+=quote_text(x);}s.add(encoded+"\n");std::size_t expected=model.blocks.size()+1+model.rigs.size();for(const auto&r:packet.rows)if(r.active){expected+=1+(r.kind!=1)+(r.query?1:0);}const auto count=s.count();require(count==expected,"complete parameter registry denominator");s.add(std::to_string(count)+"\n");
 for(const auto&b:model.blocks)s.parameter(b.name,b.values.size(),b.values.data());for(std::size_t i=0;i<n;++i)if(packet.rows[i].active&&packet.rows[i].kind!=1)s.parameter("station/"+std::to_string(i),1,&station[i]);for(std::size_t i=0;i<n;++i)if(packet.rows[i].active)s.parameter("row/"+std::to_string(i),1,&row[i]);for(std::size_t i=0;i<n;++i)if(packet.rows[i].active&&packet.rows[i].query)s.parameter("alpha/"+std::to_string(i),1,&alpha[i]);eventio::Json extras=eventio::Json::object();s.parameter("budget_sq",1,nullptr,&extras);for(const auto&r:model.rigs)s.parameter("rig/"+r.id+"/numerical_zoom_enclosure",2,nullptr,&extras);
 auto discrete=s.map();auto wanted=math.discrete;wanted["joint_packet_sha256"]=packet.source_hash;wanted["RS_profile_policy"]="explicit bounded station/row/alpha; exact original RS and finite frozen query equalities; independent true RS on export";wanted["fixed_path_table"]=packet.schema;std::string rle;for(std::size_t i=0;i<n;){std::size_t j=i+1;while(j<n&&path[j]==path[i])++j;rle+=std::to_string(j-i)+":"+std::to_string(path[i])+";";i=j;}wanted["finite_material_paths_RLE_u32_v1"]=rle;require(discrete==wanted,"fixed complete discrete registry/source/path differs");require(s.map().empty(),"unknown root-chart registry");require(s.count()==0&&s.line()=="END_RINKFIT_AL_CHECKPOINT","old best state/trailer");std::string tail;while(std::getline(s.in,tail))require(tail.find_first_not_of(" \r\n\t")==std::string::npos,"trailing state data");std::ostringstream computed;computed<<std::hex<<std::setw(16)<<std::setfill('0')<<s.hash;require(computed.str()==token.at(0),"complete FNV state token differs");
 return {{"schema","rinkfit.source_enriched_complete_checkpoint_verification.v1"},{"passed",true},{"state_token",computed.str()},{"source_packet_sha256",packet.source_hash},{"mathematical_source_id",math.identity},{"complete_parameters",count},{"explicit_all_raw_rows",n},{"source_attachment_discrete",math.discrete},{"nonphysical_state_verified_not_resumed",extras},{"old_AL_duals_resumed",false}};
